// Bundles the addon (index.js + lib/*) into ONE self-contained index.js so it's
// trivial to upload to GitHub/Render from a phone/iPad (2 files instead of 7).
// Local requires are rewritten to an internal registry; builtins (http, url) pass through.
const fs = require('fs');
const path = require('path');
const ROOT = __dirname;

const FILES = ['index.js', 'lib/stardima.js', 'lib/resolver.js', 'lib/hosts.js', 'lib/unpacker.js'];

function idOf(fromId, req) {
  const dir = path.dirname(fromId);
  let p = path.normalize(path.join(dir, req)).replace(/\\/g, '/');
  if (!p.endsWith('.js')) p += '.js';
  return p;
}

function rewrite(code, fromId) {
  return code.replace(/require\(\s*(['"])([^'"]+)\1\s*\)/g, (m, q, req) => {
    if (req.startsWith('.')) return `__req(${JSON.stringify(idOf(fromId, req))})`;
    return `__realRequire(${JSON.stringify(req)})`;
  });
}

const defs = FILES.map((f) => {
  const code = rewrite(fs.readFileSync(path.join(ROOT, f), 'utf8'), f);
  return `  ${JSON.stringify(f)}: function (module, exports, __req) {\n${code}\n  }`;
}).join(',\n');

const bundle = `// Stardima Addon — single-file bundled build (generated by build-bundle.js).
// Self-contained: no local requires, no dependencies. Run with: node index.js
(function () {
  const __realRequire = typeof require === 'function' ? require : null;
  const __defs = {
${defs}
  };
  const __cache = {};
  function __req(id) {
    if (__cache[id]) return __cache[id].exports;
    const def = __defs[id];
    if (!def) throw new Error('module not found: ' + id);
    const m = { exports: {} };
    __cache[id] = m;
    def(m, m.exports, __req);
    return m.exports;
  }
  __req('index.js');
})();
`;

const outDir = path.join(ROOT, '..');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'index.js'), bundle);
console.log('bundle written:', path.join(outDir, 'index.js'), '(' + bundle.length + ' bytes)');
